const s = $input.first().json.series.filter(p => p[1] !== null);
const v = s.map(p => p[1]);
const mean = v.reduce((a, b) => a + b, 0) / v.length;
const max = Math.max(...v);
return [{ json: { hours: v.length, mean_wind_MW: Math.round(mean), max_wind_MW: Math.round(max), note: 'German onshore wind, newest week in the SMARD feed (may be partial: see hours)' } }];
